@Override public void setPlaybackParameters(@Nullable IMediaController caller,int sequenceNumber,Bundle playbackParametersBundle){
  if (caller == null || playbackParametersBundle == null) {
    return;
  }
  try {
    PlaybackParameters playbackParameters=PlaybackParameters.fromBundle(playbackParametersBundle);
    queueSessionTaskWithPlayerCommand(caller,sequenceNumber,COMMAND_SET_SPEED_AND_PITCH,sendSessionResultSuccess(player -> player.setPlaybackParameters(playbackParameters)));
  } catch (IllegalArgumentException e) {
    // 处理 playbackParametersBundle 格式不正确的情况
    e.printStackTrace();
  } catch (IllegalStateException e) {
    // 处理播放器状态不允许设置参数的情况
    e.printStackTrace();
  }
}
